#version 300 es

precision highp float;
precision highp int;
#define HLSLCC_ENABLE_UNIFORM_BUFFERS 1
#if HLSLCC_ENABLE_UNIFORM_BUFFERS
#define UNITY_UNIFORM
#else
#define UNITY_UNIFORM uniform
#endif
#define UNITY_SUPPORTS_UNIFORM_LOCATION 1
#if UNITY_SUPPORTS_UNIFORM_LOCATION
#define UNITY_LOCATION(x) layout(location = x)
#define UNITY_BINDING(x) layout(binding = x, std140)
#else
#define UNITY_LOCATION(x)
#define UNITY_BINDING(x) layout(std140)
#endif
layout(std140) uniform f_buffer0 {
	vec4 f_cb0[9];
} _f_buffer0;
uniform highp sampler2D f_t0TEX_with_SMPf_s0;
uniform highp sampler2D f_t0;
uniform highp sampler2D f_t1TEX_with_SMPf_s2;
uniform highp sampler2D f_t1;
uniform highp sampler2D f_t2TEX_with_SMPf_s3;
uniform highp sampler2D f_t2;
uniform highp sampler2D f_t3TEX_with_SMPf_s1;
uniform highp sampler2D f_t3;
in highp vec2 vs_TEXCOORD0;
in highp vec2 vs_TEXCOORD1;
in highp vec2 vs_TEXCOORD2;
in highp vec2 vs_TEXCOORD3;
in highp vec4 vs_COLOR0;
layout(location = 0) out highp vec4 SV_Target0;
vec4 u_xlat0;
vec4 u_xlat1;
vec3 u_xlat2;
float u_xlat9;
void main()
{
    u_xlat0 = texture(f_t2TEX_with_SMPf_s3, vs_TEXCOORD2.xy);
    u_xlat0.xyz = u_xlat0.xyz * _f_buffer0.f_cb0[6].xyz;
    u_xlat9 = _f_buffer0.f_cb0[6].w + _f_buffer0.f_cb0[6].w;
    u_xlat0.xyz = vec3(u_xlat9) * u_xlat0.xyz;
    u_xlat1 = texture(f_t1TEX_with_SMPf_s2, vs_TEXCOORD1.xy);
    u_xlat1.xyz = u_xlat1.xyz * _f_buffer0.f_cb0[3].xyz;
    u_xlat9 = _f_buffer0.f_cb0[3].w + _f_buffer0.f_cb0[3].w;
    u_xlat2.xyz = u_xlat1.xyz * vec3(u_xlat9) + u_xlat0.xyz;
    u_xlat1.xyz = vec3(u_xlat9) * u_xlat1.xyz;
    u_xlat2.xyz = u_xlat2.xyz * vec3(0.5, 0.5, 0.5);
    u_xlat0.xyz = u_xlat1.xyz * u_xlat0.xyz + (-u_xlat2.xyz);
    u_xlat0.xyz = _f_buffer0.f_cb0[7].www * u_xlat0.xyz + u_xlat2.xyz;
    u_xlat0.xyz = (-u_xlat0.xyz) + _f_buffer0.f_cb0[8].zzz;
    u_xlat1 = texture(f_t0TEX_with_SMPf_s0, vs_TEXCOORD0.xy);
    u_xlat0.xyz = (-u_xlat0.xyz) * _f_buffer0.f_cb0[8].xxx + u_xlat1.xyz;
    u_xlat0.xyz = u_xlat0.xyz + _f_buffer0.f_cb0[8].yyy;
    u_xlat1.xyz = (-u_xlat0.xyz) + u_xlat1.xyz;
    u_xlat0.xyz = u_xlat1.www * u_xlat1.xyz + u_xlat0.xyz;
    u_xlat1 = texture(f_t3TEX_with_SMPf_s1, vs_TEXCOORD3.xy);
    u_xlat2.xyz = u_xlat0.xyz * u_xlat1.xyz + vec3(0.150000006, 0.150000006, 0.150000006);
    u_xlat0.xyz = u_xlat0.xyz * u_xlat1.xyz;
    u_xlat1.xyz = u_xlat2.xyz * vs_COLOR0.xyz;
    SV_Target0.xyz = min(u_xlat0.xyz, u_xlat1.xyz);
    SV_Target0.w = 1.0;
    return;
}
